using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    // --- CreateOrder ---

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2), ("Gadget", 25m, 1));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(45m, order.Total);
        Assert.HasCount(2, order.Items);
        Assert.IsNotNull(order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_ReturnsTotalEqualToItemTotal()
    {
        // Arrange
        var items = CreateItems(("Book", 15.50m, 3));

        // Act
        var order = _service.CreateOrder("cust-2", items);

        // Assert
        Assert.AreEqual(46.50m, order.Total);
        var single = Assert.ContainsSingle(order.Items);
        Assert.AreEqual("Book", single.ProductName);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = CreateItems(("Item", 5m, 1));

        // Act
        var order = _service.CreateOrder("cust-3", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsGreaterThanOrEqual(order.CreatedAt, before);
        Assert.IsLessThanOrEqual(order.CreatedAt, after);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        // Arrange
        var items = CreateItems(("Item", 5m, 1));

        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    // --- GetOrder ---

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsMatchingOrder()
    {
        // Arrange
        var items = CreateItems(("Pen", 2m, 5));
        var created = _service.CreateOrder("cust-4", items);

        // Act
        var found = _service.GetOrder(created.Id);

        // Assert
        Assert.IsNotNull(found);
        Assert.AreSame(created, found);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        // Act
        var result = _service.GetOrder("does-not-exist");

        // Assert
        Assert.IsNull(result);
    }

    // --- GetOrdersByCustomer ---

    [TestMethod]
    public void GetOrdersByCustomer_WithMultipleOrders_ReturnsAllForCustomer()
    {
        // Arrange
        _service.CreateOrder("cust-A", CreateItems(("Item1", 10m, 1)));
        _service.CreateOrder("cust-A", CreateItems(("Item2", 20m, 1)));
        _service.CreateOrder("cust-B", CreateItems(("Item3", 30m, 1)));

        // Act
        var orders = _service.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        // Act
        var orders = _service.GetOrdersByCustomer("unknown");

        // Assert
        Assert.IsEmpty(orders);
    }

    // --- Data-driven: total calculation ---

    [TestMethod]
    [DynamicData(nameof(TotalCalculationData))]
    public void CreateOrder_CalculatesCorrectTotal(
        string description, List<OrderItem> items, decimal expectedTotal)
    {
        // Act
        var order = _service.CreateOrder("cust-dd", items);

        // Assert
        Assert.AreEqual(expectedTotal, order.Total);
    }

    public static IEnumerable<object[]> TotalCalculationData =>
    [
        ["Single item, qty 1", CreateItems(("A", 10m, 1)), 10m],
        ["Single item, qty 5", CreateItems(("B", 3m, 5)), 15m],
        ["Multiple items",     CreateItems(("C", 7m, 2), ("D", 5m, 3)), 29m],
    ];
}

